namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Instructor
{
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

public class Course
{
    public string Id { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string Title { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
    public string Level { get; set; } = ""; // Undergraduate, Graduate
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    public string CourseId { get; set; } = "";

    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    [Required(ErrorMessage = "Email is required.")]
    public string Email { get; set; } = "";

    [StringLength(500)]
    public string Notes { get; set; } = "";
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and literary analysis." },
            new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = "hist", Name = "History", Description = "Examination of past events, societies, and civilizations." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = "cs101", DepartmentId = "cs", Title = "Introduction to Programming", Code = "CS 101",
                Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201",
                Instructor = new() { Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She holds a Ph.D. from MIT and specializes in CS education research.", Email = "s.chen@university.edu" },
                IsFeatured = true, Level = "Undergraduate"
            },
            new()
            {
                Id = "cs301", DepartmentId = "cs", Title = "Data Structures and Algorithms", Code = "CS 301",
                Description = "Advanced study of data structures including trees, graphs, hash tables, and heaps. Analysis of algorithm complexity and design patterns including divide-and-conquer, dynamic programming, and greedy algorithms.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", Location = "Tech Building 105",
                Instructor = new() { Name = "Dr. James Morton", Title = "Professor", Bio = "Dr. Morton is a leading researcher in algorithm design with publications in top-tier journals. He received his Ph.D. from Stanford University.", Email = "j.morton@university.edu" },
                IsFeatured = false, Level = "Undergraduate"
            },
            new()
            {
                Id = "cs450", DepartmentId = "cs", Title = "Machine Learning", Code = "CS 450",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and deep learning. Hands-on projects with real-world datasets.",
                Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", Location = "Data Science Lab 302",
                Instructor = new() { Name = "Dr. Priya Sharma", Title = "Assistant Professor", Bio = "Dr. Sharma joined the faculty after industry experience at a major tech company. Her research focuses on explainable AI and fairness in ML systems.", Email = "p.sharma@university.edu" },
                IsFeatured = true, Level = "Graduate"
            },
            new()
            {
                Id = "math201", DepartmentId = "math", Title = "Linear Algebra", Code = "MATH 201",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications to computer graphics, data science, and engineering.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Mathematics Building 110",
                Instructor = new() { Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is an award-winning educator with over 20 years of teaching experience. His textbook on linear algebra is used at universities worldwide.", Email = "r.kim@university.edu" },
                IsFeatured = true, Level = "Undergraduate"
            },
            new()
            {
                Id = "math305", DepartmentId = "math", Title = "Probability and Statistics", Code = "MATH 305",
                Description = "Foundations of probability theory, random variables, distributions, hypothesis testing, and regression analysis. Essential for data science and research methods.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", Location = "Mathematics Building 205",
                Instructor = new() { Name = "Dr. Lisa Park", Title = "Associate Professor", Bio = "Dr. Park specializes in applied statistics and biostatistics. She consults with the university medical center on clinical trial design.", Email = "l.park@university.edu" },
                IsFeatured = false, Level = "Undergraduate"
            },
            new()
            {
                Id = "eng101", DepartmentId = "eng", Title = "Composition and Rhetoric", Code = "ENG 101",
                Description = "Develop essential writing skills through essays, research papers, and peer review. Focus on argumentation, evidence-based writing, and clear communication.",
                Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities Hall 115",
                Instructor = new() { Name = "Prof. Maria Gonzalez", Title = "Senior Lecturer", Bio = "Prof. Gonzalez is a published author and writing coach. She has helped thousands of students develop strong academic writing skills over her 12-year career.", Email = "m.gonzalez@university.edu" },
                IsFeatured = false, Level = "Undergraduate"
            },
            new()
            {
                Id = "eng350", DepartmentId = "eng", Title = "American Literature", Code = "ENG 350",
                Description = "Survey of American literary traditions from the colonial period to the present. Readings include works by Hawthorne, Twain, Fitzgerald, Morrison, and contemporary authors.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", Location = "Humanities Hall 220",
                Instructor = new() { Name = "Dr. William Torres", Title = "Professor", Bio = "Dr. Torres is a Pulitzer-nominated literary critic and author of three books on American fiction. He brings passion and deep expertise to every class.", Email = "w.torres@university.edu" },
                IsFeatured = true, Level = "Undergraduate"
            },
            new()
            {
                Id = "phys201", DepartmentId = "phys", Title = "Classical Mechanics", Code = "PHYS 201",
                Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, central forces, and rigid body dynamics. Calculus-based with weekly problem sets.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Building 101",
                Instructor = new() { Name = "Dr. Alan Foster", Title = "Professor", Bio = "Dr. Foster is a theoretical physicist whose research spans classical and quantum mechanics. He is known for his engaging lectures and innovative teaching methods.", Email = "a.foster@university.edu" },
                IsFeatured = false, Level = "Undergraduate"
            },
            new()
            {
                Id = "hist101", DepartmentId = "hist", Title = "World History to 1500", Code = "HIST 101",
                Description = "A global survey of human civilizations from prehistory through the late medieval period. Covers Mesopotamia, Egypt, Greece, Rome, China, the Islamic world, and the Americas.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", Location = "Liberal Arts 305",
                Instructor = new() { Name = "Dr. Eleanor Wright", Title = "Associate Professor", Bio = "Dr. Wright is an archaeologist and historian specializing in ancient Mediterranean cultures. She leads annual student excavation trips to Greece and Turkey.", Email = "e.wright@university.edu" },
                IsFeatured = false, Level = "Undergraduate"
            },
            new()
            {
                Id = "hist410", DepartmentId = "hist", Title = "Modern European History", Code = "HIST 410",
                Description = "Europe from the French Revolution to the present day. Examines political revolutions, industrialization, world wars, the Cold War, and European integration.",
                Credits = 3, Schedule = "Mon/Wed 4:00–5:15 PM", Location = "Liberal Arts 210",
                Instructor = new() { Name = "Dr. Heinrich Bauer", Title = "Professor", Bio = "Dr. Bauer is a German-born historian specializing in 20th-century European politics. He has authored five books and serves as a consultant for historical documentaries.", Email = "h.bauer@university.edu" },
                IsFeatured = true, Level = "Graduate"
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, string? departmentId, string? level)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId == departmentId);

        if (!string.IsNullOrWhiteSpace(level))
            query = query.Where(c => c.Level == level);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

