@page "/courses"
@rendermode InteractiveServer

@inject CatalogService Catalog

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-5">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor…"
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="SelectedDepartment">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetDepartments())
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <select class="form-select" @bind="SelectedLevel">
            <option value="">All Levels</option>
            <option value="Undergraduate">Undergraduate</option>
            <option value="Graduate">Graduate</option>
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@{
    var results = Catalog.SearchCourses(SearchTerm, SelectedDepartment, SelectedLevel);
}

<p class="text-muted">Showing @results.Count course@(results.Count != 1 ? "s" : "")</p>

@if (results.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria. Try adjusting your filters.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Level</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in results)
            {
                var dept = Catalog.GetDepartment(course.DepartmentId);
                <tr>
                    <td><strong>@course.Code</strong></td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Level</td>
                    <td>@course.Instructor.Name</td>
                    <td>
                        <a href="courses/@course.Id" class="btn btn-sm btn-primary">Details</a>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? DepartmentId { get; set; }

    private string SearchTerm { get; set; } = "";
    private string SelectedDepartment { get; set; } = "";
    private string SelectedLevel { get; set; } = "";

    protected override void OnInitialized()
    {
        if (!string.IsNullOrWhiteSpace(DepartmentId))
        {
            SelectedDepartment = DepartmentId;
        }
    }

    private void ClearFilters()
    {
        SearchTerm = "";
        SelectedDepartment = "";
        SelectedLevel = "";
    }
}

@page "/enroll"

@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive a confirmation email once your request is processed.</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
            <strong>@(Catalog.GetCourse(Model.CourseId)?.Code ?? Model.CourseId)</strong>
            has been submitted successfully.</p>
        <p class="mb-0">A confirmation will be sent to <strong>@Model.Email</strong>.</p>
    </div>
    <a href="enroll" class="btn btn-primary">Submit Another Request</a>
    <a href="" class="btn btn-outline-secondary ms-2">Return Home</a>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label for="fullName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <InputText id="fullName" class="form-control" @bind-Value="Model.FullName" />
                    <ValidationMessage For="() => Model.FullName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" placeholder="e.g. STU-12345" />
                    <ValidationMessage For="() => Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                    <InputText id="email" class="form-control" type="email" @bind-Value="Model.Email" />
                    <ValidationMessage For="() => Model.Email" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                        <option value="">— Select a course —</option>
                        @foreach (var course in Catalog.GetAllCourses())
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.CourseId" />
                </div>

                <div class="mb-3">
                    <label for="notes" class="form-label">Additional Notes</label>
                    <InputTextArea id="notes" class="form-control" rows="3" @bind-Value="Model.Notes" />
                    <ValidationMessage For="() => Model.Notes" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </div>
        </div>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private bool Submitted { get; set; }

    protected override void OnInitialized()
    {
        if (!string.IsNullOrWhiteSpace(CourseId) && string.IsNullOrEmpty(Model.CourseId))
        {
            Model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        Submitted = true;
    }
}

